#[test]
fn max_message_bytes_limits_new_bodies_only() {
    let mut h = Harness::new();
    create(&mut h, "q", json!({"MaxMessageBytes": 4}));
    let attrs = h.ok(json!({"Command": "GetQueueAttributes", "QueueName": "q"}));
    assert_eq!(attrs["Attributes"]["MaxMessageBytes"], 4);
    send(&mut h, "q", "abcd");
    // "é" is 2 bytes in UTF-8: 3 chars but 5 bytes.
    let over = json!({"Command": "SendMessage", "QueueName": "q", "Body": "abcé"});
    assert_eq!(h.err(over), "InvalidParameterValue");
    send(&mut h, "q", "abé");

    h.ok(json!({"Command": "SetQueueAttributes", "QueueName": "q",
        "Attributes": {"MaxMessageBytes": 2}}));
    assert_eq!(receive(&mut h, "q", 10).len(), 2, "old messages stay");
    let over = json!({"Command": "SendMessage", "QueueName": "q", "Body": "abc"});
    assert_eq!(h.err(over), "InvalidParameterValue");
}

#[test]
fn max_message_bytes_defaults_and_range() {
    let mut h = Harness::new();
    create(&mut h, "q", json!({}));
    let attrs = h.ok(json!({"Command": "GetQueueAttributes", "QueueName": "q"}));
    assert_eq!(attrs["Attributes"]["MaxMessageBytes"], 1024);
    for bad in [json!(0), json!(1025), json!("5")] {
        let c = json!({"Command": "CreateQueue", "QueueName": "r",
            "Attributes": {"MaxMessageBytes": bad}});
        assert_eq!(h.err(c), "InvalidParameterValue");
    }
    // Takes part in the idempotent-create comparison.
    let c = json!({"Command": "CreateQueue", "QueueName": "q",
        "Attributes": {"MaxMessageBytes": 10}});
    assert_eq!(h.err(c), "QueueAlreadyExists");
    h.ok(json!({"Command": "CreateQueue", "QueueName": "q",
        "Attributes": {"MaxMessageBytes": 1024}}));
}

#[test]
fn max_message_bytes_comes_before_fifo_checks() {
    let mut h = Harness::new();
    create(&mut h, "q.fifo", json!({"Fifo": true, "MaxMessageBytes": 1}));
    // Without GroupId this would be MissingParameter; the size rule wins.
    let c = json!({"Command": "SendMessage", "QueueName": "q.fifo", "Body": "ab"});
    assert_eq!(h.err(c), "InvalidParameterValue");
}
