mod common;

use common::Harness;
use serde_json::json;

fn setup() -> Harness {
    let mut h = Harness::new();
    h.ok(json!({"Command": "CreateQueue", "QueueName": "q"}));
    h
}

fn tags(h: &mut Harness) -> serde_json::Value {
    h.ok(json!({"Command": "ListQueueTags", "QueueName": "q"}))["Tags"].clone()
}

fn tag(h: &mut Harness, t: serde_json::Value) {
    h.ok(json!({"Command": "TagQueue", "QueueName": "q", "Tags": t}));
}

#[test]
fn tag_replace_and_untag() {
    let mut h = setup();
    assert_eq!(tags(&mut h), json!({}));
    tag(&mut h, json!({"a": "1", "b": "", "C-_": "x"}));
    tag(&mut h, json!({"a": "2"}));
    assert_eq!(tags(&mut h), json!({"a": "2", "b": "", "C-_": "x"}));
    h.ok(json!({"Command": "UntagQueue", "QueueName": "q", "TagKeys": ["a", "zzz"]}));
    assert_eq!(tags(&mut h), json!({"b": "", "C-_": "x"}));
    h.ok(json!({"Command": "UntagQueue", "QueueName": "q", "TagKeys": []}));
    tag(&mut h, json!({}));
    assert_eq!(tags(&mut h), json!({"b": "", "C-_": "x"}));
    // Keys are case-sensitive.
    tag(&mut h, json!({"B": "up"}));
    assert_eq!(tags(&mut h)["B"], "up");
    assert_eq!(tags(&mut h)["b"], "");
}

#[test]
fn value_and_key_validation() {
    let mut h = setup();
    let bad = [
        json!({"a b": "x"}),
        json!({"": "x"}),
        json!({"k".repeat(129): "x"}),
        json!({"a": 1}),
        json!({"a": null}),
        json!({"a": "x".repeat(257)}),
    ];
    for t in bad {
        let c = json!({"Command": "TagQueue", "QueueName": "q", "Tags": t});
        assert_eq!(h.err(c), "InvalidParameterValue");
    }
    // 256 bytes is fine even if it is 128 characters; 129 two-byte chars is not.
    tag(&mut h, json!({"a": "é".repeat(128), "k".repeat(128): "x"}));
    let c = json!({"Command": "TagQueue", "QueueName": "q", "Tags": {"b": "é".repeat(129)}});
    assert_eq!(h.err(c), "InvalidParameterValue");
    for keys in [json!([1]), json!(["a b"])] {
        let c = json!({"Command": "UntagQueue", "QueueName": "q", "TagKeys": keys});
        assert_eq!(h.err(c), "InvalidParameterValue");
    }
    let c = json!({"Command": "TagQueue", "QueueName": "q", "Tags": []});
    assert_eq!(h.err(c), "InvalidParameterValue");
}

#[test]
fn missing_and_unknown_queue_order() {
    let mut h = setup();
    assert_eq!(h.err(json!({"Command": "TagQueue", "QueueName": "q"})), "MissingParameter");
    assert_eq!(h.err(json!({"Command": "UntagQueue", "QueueName": "q"})), "MissingParameter");
    assert_eq!(h.err(json!({"Command": "ListQueueTags"})), "MissingParameter");
    // Value errors (step 3) come before the lookup (step 4).
    let c = json!({"Command": "TagQueue", "QueueName": "nope", "Tags": {"a": 1}});
    assert_eq!(h.err(c), "InvalidParameterValue");
    let c = json!({"Command": "TagQueue", "QueueName": "nope", "Tags": {"a": "1"}});
    assert_eq!(h.err(c), "QueueDoesNotExist");
    assert_eq!(h.err(json!({"Command": "ListQueueTags", "QueueName": "nope"})), "QueueDoesNotExist");
}

#[test]
fn limit_of_fifty_counts_resulting_tags() {
    let mut h = setup();
    let many = |range: std::ops::Range<u32>| {
        range.map(|i| (format!("k{i}"), json!("v"))).collect::<serde_json::Map<_, _>>()
    };
    tag(&mut h, json!(many(0..50)));
    // Replacing existing keys keeps the count at 50.
    tag(&mut h, json!(many(0..50)));
    // One new key would make 51; nothing at all is applied.
    let mut over = many(0..2);
    over.insert("new".into(), json!("v"));
    let c = json!({"Command": "TagQueue", "QueueName": "q", "Tags": over});
    assert_eq!(h.err(c), "LimitExceeded");
    assert!(tags(&mut h).get("new").is_none());
    h.ok(json!({"Command": "UntagQueue", "QueueName": "q", "TagKeys": ["k0"]}));
    tag(&mut h, json!({"new": "v"}));
    assert_eq!(tags(&mut h).as_object().unwrap().len(), 50);
}

#[test]
fn tags_are_not_attributes_and_survive_purge_but_not_delete() {
    let mut h = setup();
    tag(&mut h, json!({"a": "1"}));
    let attrs = h.ok(json!({"Command": "GetQueueAttributes", "QueueName": "q"}));
    assert!(attrs["Attributes"].get("Tags").is_none());
    // CreateQueue rule 4 ignores tags.
    h.ok(json!({"Command": "CreateQueue", "QueueName": "q"}));
    h.ok(json!({"Command": "PurgeQueue", "QueueName": "q"}));
    assert_eq!(tags(&mut h), json!({"a": "1"}));
    h.ok(json!({"Command": "DeleteQueue", "QueueName": "q"}));
    h.ok(json!({"Command": "CreateQueue", "QueueName": "q"}));
    assert_eq!(tags(&mut h), json!({}));
}
